import { useState } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';

export default function Login() {
  const [form, setForm] = useState({ email: '', password: '' });
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const [showPass, setShowPass] = useState(false);
  const { login } = useAuth();
  const navigate = useNavigate();

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    setLoading(true);
    try {
      await login(form.email, form.password);
      navigate('/dashboard');
    } catch (err) {
      setError(err.response?.data?.message || 'Invalid email or password');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div style={styles.page}>
      {/* Left Panel */}
      <div style={styles.left}>
        <div style={styles.leftContent}>
          <div style={styles.brand}>🗂 DRMS</div>
          <h1 style={styles.heroTitle}>Digital Records<br />Management System</h1>
          <p style={styles.heroSub}>Securely manage, organize, and retrieve your organization's documents with role-based access control.</p>
          <div style={styles.features}>
            {['🔒 Role-Based Access Control', '📁 Document Version Control', '📊 Reports & Analytics', '🔍 Audit Trail Logging'].map(f => (
              <div key={f} style={styles.featureItem}>{f}</div>
            ))}
          </div>
        </div>
      </div>

      {/* Right Panel */}
      <div style={styles.right}>
        <div style={styles.card}>
          <div style={styles.cardHeader}>
            <h2 style={styles.cardTitle}>Welcome back</h2>
            <p style={styles.cardSub}>Sign in to your account</p>
          </div>

          {error && <div style={styles.errorBox}>⚠️ {error}</div>}

          <form onSubmit={handleSubmit}>
            <div style={styles.field}>
              <label style={styles.label}>Email Address</label>
              <div style={styles.inputWrap}>
                <span style={styles.inputIcon}>✉️</span>
                <input style={styles.input} type="email" placeholder="you@example.com"
                  value={form.email} onChange={e => setForm({ ...form, email: e.target.value })} required />
              </div>
            </div>

            <div style={styles.field}>
              <label style={styles.label}>Password</label>
              <div style={styles.inputWrap}>
                <span style={styles.inputIcon}>🔑</span>
                <input style={styles.input} type={showPass ? 'text' : 'password'} placeholder="Enter your password"
                  value={form.password} onChange={e => setForm({ ...form, password: e.target.value })} required />
                <span style={styles.eyeBtn} onClick={() => setShowPass(!showPass)}>{showPass ? '🙈' : '👁'}</span>
              </div>
            </div>

            <button style={{ ...styles.btn, opacity: loading ? 0.7 : 1 }} type="submit" disabled={loading}>
              {loading ? '⏳ Signing in...' : '→  Sign In'}
            </button>
          </form>

          <p style={styles.footer}>Don't have an account? <Link to="/register" style={styles.link}>Create one</Link></p>

          <div style={styles.demoBox}>
            <p style={styles.demoTitle}>Demo Credentials</p>
            {[
              { role: 'Admin',   email: 'admin@drms.com',   pass: 'Admin@123',   color: '#ef4444' },
              { role: 'Manager', email: 'manager@drms.com', pass: 'Manager@123', color: '#f59e0b' },
              { role: 'User',    email: 'tk@drms.com',      pass: 'User@123',    color: '#10b981' },
              { role: 'Auditor', email: 'auditor@drms.com', pass: 'Auditor@123', color: '#6366f1' },
            ].map(d => (
              <div key={d.role} style={styles.demoRow} onClick={() => setForm({ email: d.email, password: d.pass })}>
                <span style={{ ...styles.demoRole, background: d.color }}>{d.role}</span>
                <span style={styles.demoEmail}>{d.email}</span>
                <span style={styles.demoPass}>{d.pass}</span>
              </div>
            ))}
            <p style={styles.demoHint}>👆 Click any row to auto-fill</p>
          </div>
        </div>
      </div>
    </div>
  );
}

const styles = {
  page: { display: 'flex', minHeight: '100vh' },

  // Left side - gradient with white text
  left: {
    flex: 1,
    background: 'linear-gradient(135deg, #4f46e5 0%, #7c3aed 50%, #6366f1 100%)',
    display: 'flex', alignItems: 'center', justifyContent: 'center', padding: '48px',
  },
  leftContent: { maxWidth: '420px' },
  brand: { fontSize: '24px', fontWeight: '700', color: '#ffffff', marginBottom: '32px' },
  heroTitle: { fontSize: '38px', fontWeight: '700', lineHeight: '1.2', marginBottom: '16px', color: '#ffffff' },
  heroSub: { fontSize: '16px', color: 'rgba(255,255,255,0.85)', lineHeight: '1.7', marginBottom: '32px' },
  features: { display: 'flex', flexDirection: 'column', gap: '12px' },
  featureItem: {
    display: 'flex', alignItems: 'center', gap: '10px',
    fontSize: '15px', color: '#ffffff',
    background: 'rgba(255,255,255,0.15)',
    padding: '10px 16px', borderRadius: '8px',
    backdropFilter: 'blur(4px)',
  },

  // Right side - white card
  right: {
    width: '480px', display: 'flex', alignItems: 'center',
    justifyContent: 'center', padding: '32px',
    background: 'rgba(255,255,255,0.6)', backdropFilter: 'blur(20px)',
  },
  card: {
    width: '100%', background: '#ffffff',
    borderRadius: '16px', padding: '36px',
    boxShadow: '0 8px 32px rgba(79,70,229,0.12)',
  },
  cardHeader: { marginBottom: '24px' },
  cardTitle: { fontSize: '24px', fontWeight: '700', color: '#1e293b', marginBottom: '4px' },
  cardSub: { color: '#64748b', fontSize: '14px' },
  errorBox: {
    background: '#fef2f2', border: '1px solid #fecaca',
    color: '#dc2626', padding: '10px 14px',
    borderRadius: '8px', fontSize: '13px', marginBottom: '16px',
  },
  field: { marginBottom: '18px' },
  label: { display: 'block', fontSize: '13px', fontWeight: '600', color: '#374151', marginBottom: '6px' },
  inputWrap: { position: 'relative', display: 'flex', alignItems: 'center' },
  inputIcon: { position: 'absolute', left: '12px', fontSize: '15px' },
  input: {
    width: '100%', padding: '10px 12px 10px 38px',
    border: '1.5px solid #e2e8f0', borderRadius: '8px',
    fontSize: '14px', outline: 'none', background: '#f8fafc',
    color: '#1e293b', boxSizing: 'border-box',
  },
  eyeBtn: { position: 'absolute', right: '12px', cursor: 'pointer', fontSize: '15px' },
  btn: {
    width: '100%', padding: '12px',
    background: 'linear-gradient(135deg, #4f46e5, #7c3aed)',
    color: '#ffffff', border: 'none', borderRadius: '8px',
    fontSize: '15px', fontWeight: '600', cursor: 'pointer', marginTop: '4px',
  },
  footer: { textAlign: 'center', marginTop: '20px', fontSize: '13px', color: '#64748b' },
  link: { color: '#4f46e5', fontWeight: '600' },
  demoBox: {
    marginTop: '20px', background: '#f8fafc',
    border: '1px solid #e2e8f0', borderRadius: '10px', padding: '14px',
  },
  demoTitle: {
    fontSize: '11px', fontWeight: '700', color: '#94a3b8',
    textTransform: 'uppercase', letterSpacing: '0.5px', marginBottom: '10px',
  },
  demoRow: {
    display: 'flex', alignItems: 'center', gap: '8px',
    padding: '7px 8px', borderRadius: '6px', cursor: 'pointer', marginBottom: '4px',
